// LockForUpdate adds "FOR UPDATE" (Postgres, MySQL; ignored on SQLite).
//
// Example:
//
//	conn.Select().From("accounts").Where("id", 1).LockForUpdate()
//	// Postgres: SELECT * FROM "accounts" WHERE "id" = $1 FOR UPDATE   args: [1]
