// Example:
//
//	sqlText, args, err := conn.Select().From("orders").Where("status", "paid").AggregateSQL("sum", "total")
//	// SELECT SUM("total") AS "aggregate" FROM "orders" WHERE "status" = $1   args: ["paid"]
