//	// SELECT * FROM "users" WHERE "active" = $1 OR ("role" = $2 AND "age" > $3)
//	//     args: [true admin 30]
func (d *DeleteBuilder) OrWhereGroup(fn func(*WhereClause)) *DeleteBuilder {
	var fnFn func(*query)
	if fn != nil {
		fnFn = func(q *query) { fn(&WhereClause{q: q}) }
	}
	d.q.OrWhereGroup(fnFn)
	return d
}

